package io.ivo.mp3;
import io.ivo.container.*;import io.ivo.engine.*;import io.ivo.util.*;import java.nio.file.*;import java.util.*;
public class PreviousVectorBenchmark {
 public static void main(String[] args)throws Exception{byte[] b=Files.readAllBytes(Path.of(args[0]));byte[] v3=ReservoirTrial.combineV3(b,ReservoirTrial.encodeExactV1(b)),best=v3;for(int mode=1;mode<=2;mode++){byte[] p=ReservoirTrial.encodeV4(b,v3,mode);if(p.length<best.length)best=p;}for(byte[] p:ReservoirTrial.encodeSideCandidates(b,best))if(p.length<best.length)best=p;byte[] seed=best;for(byte[] p:ReservoirTrial.encodeBlockCandidates(b,seed))if(p.length<best.length)best=p;seed=best;for(int scheme=0;scheme<6;scheme++){byte[] p=ReservoirTrial.encodeMainCandidate(b,seed,scheme);if(p.length<best.length)best=p;}byte[] decoded=switch(best[3]){case '3'->ReservoirTrial.decodeV3(best);case '4'->ReservoirTrial.decodeV4(best);case '5'->ReservoirTrial.decodeSideCandidate(best);case '6'->ReservoirTrial.decodeBlockCandidate(best);case '7'->ReservoirTrial.decodeMainCandidate(best);default->throw new AssertionError();};if(!Arrays.equals(decoded,b))throw new AssertionError();byte[] packed=IvoContainer.pack(new IvoArchive(EngineId.MP3_V1,b.length,Path.of(args[0]).getFileName().toString(),Hashing.sha256(b),best));Files.write(Path.of(args[1]),packed);System.out.println("PREVIOUS same_name=true ivo="+packed.length+" exact=true magic="+(char)best[3]);}
}
